  "tour.welcome.title": "Welcome to CONTIX",
  "tour.welcome.text": "A short tour shows where to find the essentials. You can start it again any time from the Help panel (question mark at the bottom right).",
  "tour.my.title": "My work",
  "tour.my.text": "Everything you need to do: documents to acknowledge, trainings and tasks with due dates. The number in the menu shows how many tasks are waiting.",
  "tour.docs.title": "Documents",
  "tour.docs.text": "Valid directives and procedures. Search the text, confirm acknowledgement and send a comment when something is unclear.",
  "tour.report.title": "Report an event",
  "tour.report.text": "Report a suspicious e-mail, a lost laptop or unusual system behaviour right away – better too often than too rarely.",
  "tour.policies.title": "Document management",
  "tour.policies.text": "The document owner prepares new versions here (from a template or in Word), the process owner reviews and the approver approves. Tasks arrive in My obligations.",
  "tour.risks.title": "Risks, controls and compliance",
  "tour.risks.text": "Risk register, treatment plan, control catalog and the Statement of Applicability. The Overview at the top left shows the status of the whole organization.",
  "tour.setup.title": "Setup wizard",
  "tour.setup.text": "In Administration you will find the wizard for the initial setup of the organization and the handover protocol.",
  "tour.help.title": "Help",
  "tour.help.text": "The question mark at the bottom right opens help for the current screen. You can download the whole manual as Word or print it to PDF.",
